32	static void write_bytes(const char *path, const uint8_t *data, size_t n)
33	{
34	  FILE *f = fopen(path, "wb");
35	
36	  if (f == NULL)
37	    {
38	      printf("cannot create %s\n", path);
39	      exit(2);
40	    }
41	
42	  fwrite(data, 1, n, f);
43	  fclose(f);
44	}
