46	static void put16(uint8_t *p, uint16_t v)
47	{
48	  p[0] = (uint8_t)v;
49	  p[1] = (uint8_t)(v >> 8);
50	}
51	
52	static void put32(uint8_t *p, uint32_t v)
53	{
54	  p[0] = (uint8_t)v;
55	  p[1] = (uint8_t)(v >> 8);
56	  p[2] = (uint8_t)(v >> 16);
57	  p[3] = (uint8_t)(v >> 24);
58	}
