60	static void make_stereo(const char *path, const int16_t *frames, int n)
61	{
62	  uint8_t hdr[44];
63	  uint8_t *buf = malloc(sizeof(hdr) + (size_t)n * 4);
64	  int i;
65	
66	  memset(hdr, 0, sizeof(hdr));
67	  memcpy(hdr, "RIFF", 4);
68	  put32(hdr + 4, (uint32_t)n * 4 + 36);
69	  memcpy(hdr + 8, "WAVEfmt ", 8);
70	  put32(hdr + 16, 16);
71	  put16(hdr + 20, 1);
72	  put16(hdr + 22, 2);
73	  put32(hdr + 24, 16000);
74	  put32(hdr + 28, 16000 * 4);
75	  put16(hdr + 32, 4);
76	  put16(hdr + 34, 16);
77	  memcpy(hdr + 36, "data", 4);
78	  put32(hdr + 40, (uint32_t)n * 4);
79	
80	  memcpy(buf, hdr, sizeof(hdr));
81	
82	  for (i = 0; i < n; i++)
83	    {
84	      put16(buf + 44 + i * 4, (uint16_t)frames[2 * i]);
85	      put16(buf + 46 + i * 4, (uint16_t)frames[2 * i + 1]);
86	    }
87	
88	  write_bytes(path, buf, sizeof(hdr) + (size_t)n * 4);
89	  free(buf);
90	}
