92	static void test_probe_and_downmix(void)
93	{
94	  struct vg_pcm_wav info;
95	  int16_t frames[8] = { 100, -100, 200, -200, 300, -300, 400, -400 };
96	  int16_t mono[4];
97	  FILE *f;
98	
99	  make_stereo(TMP_STEREO, frames, 4);
100	
101	  CHECK(vg_pcm_wav_probe(TMP_STEREO, &info) == 0);
102	  CHECK(info.rate == 16000);
103	  CHECK(info.channels == 2);
104	  CHECK(info.bits == 16);
105	  CHECK(info.data_off == 44);
106	  CHECK(info.data_bytes == 16);
107	
108	  CHECK(vg_pcm_wav_downmix_mono(TMP_STEREO, TMP_MONO) == 0);
109	  CHECK(vg_pcm_wav_probe(TMP_MONO, &info) == 0);
110	  CHECK(info.channels == 1);
111	  CHECK(info.data_bytes == 8);
112	
113	  f = fopen(TMP_MONO, "rb");
114	  CHECK(f != NULL);
115	  if (f != NULL)
116	    {
117	      CHECK(fseek(f, 44, SEEK_SET) == 0);
118	      CHECK(fread(mono, 2, 4, f) == 4);
119	      fclose(f);
120	    }
121	
122	  CHECK(mono[0] == 100);
123	  CHECK(mono[1] == 200);
124	  CHECK(mono[2] == 300);
125	  CHECK(mono[3] == 400);
126	
127	  /* A file that is not RIFF is refused rather than half-read. */
128	
129	  write_bytes(TMP_OUT, (const uint8_t *)"not a wav at all", 16);
130	  CHECK(vg_pcm_wav_probe(TMP_OUT, &info) != 0);
131	}
