133	static void test_resample(void)
134	{
135	  /* 6 input samples -> 4 output.  The first output lands on input 0, the
136	   * second halfway between 1 and 2, the third on 3, the fourth halfway
137	   * between 4 and 5. */
138	
139	  int16_t in[6] = { 0, 100, 200, 300, 400, 500 };
140	  int16_t out[8];
141	
142	  CHECK(vg_pcm_resample_24k_16k(in, 6, out, 8) == 4);
143	  CHECK(out[0] == 0);
144	  CHECK(out[1] == 150);
145	  CHECK(out[2] == 300);
146	  CHECK(out[3] == 450);
147	
148	  /* A partial group at the end is dropped, not padded with silence. */
149	
150	  CHECK(vg_pcm_resample_24k_16k(in, 5, out, 8) == 2);
151	
152	  /* Output capacity is respected. */
153	
154	  CHECK(vg_pcm_resample_24k_16k(in, 6, out, 2) == 2);
155	}
