170	static void test_base64(void)
171	{
172	  const uint8_t data[10] = { 0, 1, 2, 3, 250, 251, 252, 253, 254, 255 };
173	  char enc[64];
174	  uint8_t dec[16];
175	  struct vg_b64_stream s;
176	  size_t n = 0;
177	  int i;
178	
179	  /* Fed one byte at a time, which is what a file reader does at the end of
180	   * a chunk. */
181	
182	  memset(&s, 0, sizeof(s));
183	
184	  for (i = 0; i < 10; i++)
185	    {
186	      n += vg_b64_stream_feed(&s, data + i, 1, enc + n, sizeof(enc) - n);
187	    }
188	
189	  n += vg_b64_stream_finish(&s, enc + n, sizeof(enc) - n);
190	  enc[n] = '\0';
191	
192	  CHECK(n == 16); /* ceil(10/3)*4 */
193	
194	  {
195	    int got = vg_b64_decode(enc, n, dec, sizeof(dec));
196	
197	    CHECK(got == 10);
198	    CHECK(memcmp(dec, data, 10) == 0);
199	  }
200	
201	  /* Known vector: "Man" -> "TWFu". */
202	
203	  memset(&s, 0, sizeof(s));
204	  n = vg_b64_stream_feed(&s, (const uint8_t *)"Man", 3, enc, sizeof(enc));
205	  n += vg_b64_stream_finish(&s, enc + n, sizeof(enc) - n);
206	  enc[n] = '\0';
207	  CHECK(strcmp(enc, "TWFu") == 0);
208	
209	  /* Padding: "Ma" -> "TWE=". */
210	
211	  memset(&s, 0, sizeof(s));
212	  n = vg_b64_stream_feed(&s, (const uint8_t *)"Ma", 2, enc, sizeof(enc));
213	  n += vg_b64_stream_finish(&s, enc + n, sizeof(enc) - n);
214	  enc[n] = '\0';
215	  CHECK(strcmp(enc, "TWE=") == 0);
216	
217	  CHECK(vg_b64_decode("!!!!", 4, dec, sizeof(dec)) < 0);
218	}
