220	static void test_sse(void)
221	{
222	  char out[64];
223	
224	  CHECK(vg_sse_line_data("data: {\"a\":1}\r\n", 14, out, sizeof(out)) == 1);
225	  CHECK(strcmp(out, "{\"a\":1}") == 0);
226	
227	  CHECK(vg_sse_line_data(": keep-alive", 12, out, sizeof(out)) == 0);
228	  CHECK(vg_sse_line_data("event: message", 14, out, sizeof(out)) == 0);
229	  CHECK(vg_sse_line_data("data: [DONE]", 12, out, sizeof(out)) == -1);
230	
231	  /* A payload that does not fit is reported, not truncated: a cut base64
232	   * string decodes to garbage PCM. */
233	
234	  CHECK(vg_sse_line_data("data: 0123456789", 16, out, 4) == -2);
235	}
