239	  test_probe_and_downmix();
240	  test_resample();
241	  test_wav_write();
242	  test_base64();
243	  test_sse();
244	
245	  remove(TMP_STEREO);
246	  remove(TMP_MONO);
247	  remove(TMP_OUT);
248	
249	  if (g_fail == 0)
250	    {
251	      printf("test_voice_pcm: ok\n");
252	      return 0;
253	    }
254	
255	  printf("test_voice_pcm: %d failure(s)\n", g_fail);
256	  return 1;
257	}
