      pthread_mutex_lock(&g_pl.lock);
      if (g_pl.abort_req) { pthread_mutex_unlock(&g_pl.lock); return -EPIPE; }
      uint32_t used = g_pl.wr - g_pl.rd;
      uint32_t freeb = VG_TTS_RING_BYTES - used;
      if (freeb == 0)
