                                        struct vc_tts_sink *sink,
                                        const vela_req_ctl_t *ctl,
                                        struct vg_vc_info *info,
                                        struct timespec *mono_start)
{
  char escaped[VG_VC_TEXT_MAX * 2];
  char *body = NULL;
  char resp[VC_RESP_MAX];
