static bool voice_slot_drain(tls_ctx_t *ctx, uint32_t budget_ms, size_t cap_bytes)
{
    unsigned char drain[512];
    struct timeval tv = { .tv_sec = 0, .tv_usec = 10000 };
    uint32_t t0 = agent_mono_ms();
