{
  /* 6 input samples -> 4 output.  The first output lands on input 0, the
   * second halfway between 1 and 2, the third on 3, the fourth halfway
   * between 4 and 5. */

  int16_t in[6] = { 0, 100, 200, 300, 400, 500 };
